WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_seg_time'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '按时间分段', 'kp-trv-seg-time', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "按时间分段变速"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "行驶过程中，每过固定时间速度发生变化。列时间轴方程。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“汽车前 2 小时速度是 50，因为下雨，后面的时间里速度降为了 30。最后总共跑了 200 km。问一共开了多久？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[将整个行程切分成时间确定的前半段和未知的后半段] --> B[算前半段的路程: 50 × 2 = 100]\nB --> C[算剩下还要跑多远: 200 - 100 = 100]\nC --> D[用剩余路程除以后半段的新速度: 100 / 30 = 3.33h]\nD --> E[总时间 = 2 + 3.33 = 5.33h]"}}]}$$ AS jsonb), NULL, '按时间分段的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "按时间分段"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_seg_time", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
